        D = new int[Q + 1];
        delTime = new int[N + 1];
        Arrays.fill(delTime, Q + 1);
        for (int t = 1; t <= Q; t++) {
            int d = Integer.parseInt(br.readLine());
            D[t] = d;
            delTime[d] = t;
        }

        x = new long[N + 1];
        y = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            x[i] = A[i] - i;
            y[i] = A[i] + i;
        }

        buildLists();

        parent = new int[N + 1];
        L = new int[N + 1];
        R = new int[N + 1];
        size = new int[N + 1];
        active = new boolean[N + 1];
        for (int i = 1; i <= N; i++) {
            parent[i] = i;
            L[i] = R[i] = i;
            size[i] = 1;
