        for (int i = 1; i <= N; i++) {
            long val = x[i];
            Integer id = mapX.get(val);
            if (id == null) {
                id = mapX.size();
                mapX.put(val, id);
                listsX.add(new ArrayList<>());
            }
            listsX.get(id).add(i);
        }
        listX = new int[listsX.size()][];
        for (int i = 0; i < listsX.size(); i++) {
            ArrayList<Integer> list = listsX.get(i);
            int[] arr = new int[list.size()];
            for (int j = 0; j < arr.length; j++) arr[j] = list.get(j);
            listX[i] = arr;
        }

