        while (parent[root] != root) root = parent[root];
        while (parent[v] != v) {
            int next = parent[v];
            parent[v] = root;
            v = next;
        }
        return root;
    }

    static void addPosition(int d) {
        active[d] = true;
        int leftRoot = -1, rightRoot = -1;
        if (d > 1 && active[d - 1]) leftRoot = find(d - 1);
        if (d < N && active[d + 1]) rightRoot = find(d + 1);

        long newPairs = 0;
