            parent[leftRoot] = d;
            L[d] = L[leftRoot];
            size[d] += size[leftRoot];
        }
        if (rightRoot != -1) {
            parent[rightRoot] = d;
            R[d] = R[rightRoot];
            size[d] += size[rightRoot];
        }
    }

    static long crossCount(int L1, int R1, int L2, int R2) {
        long res = 0;
        int len1 = R1 - L1 + 1;
        int len2 = R2 - L2 + 1;

        if (len1 <= len2) {
            for (int i = L1; i <= R1; i++) {
                long jEq = i + K;
                int r = R2;
                if (jEq < R2) r = (int) jEq;
                if (L2 > r) continue;

                long cnt = countX(xMinusId[i], L2, r) + countY(yPlusId[i], L2, r);
                if (jEq >= L2 && jEq <= R2) {
                    int jj = (int) jEq;
                    if (A[i] == A[jj]) cnt--;
                }
                res += cnt;
            }
        } else {
            for (int j = L2; j <= R2; j++) {
