                if (iEq >= L1 && iEq <= R1) {
                    int ii = (int) iEq;
                    if (A[ii] == A[j]) cnt--;
                }
                res += cnt;
            }
        }
        return res;
    }

    static long pointToLeft(int d, int L, int R) {
        long iEq = d - K;
        int l = L;
        if (iEq > L) l = (int) iEq;
        if (l > R) return 0;

        long cnt = countX(xPlusId[d], l, R) + countY(yMinusId[d], l, R);
        if (iEq >= L && iEq <= R) {
            int ii = (int) iEq;
            if (A[ii] == A[d]) cnt--;
        }
        return cnt;
    }

    static long pointToRight(int d, int L, int R) {
        long jEq = d + K;
        int r = R;
        if (jEq < R) r = (int) jEq;
        if (L > r) return 0;

        long cnt = countX(xMinusId[d], L, r) + countY(yPlusId[d], L, r);
        if (jEq >= L && jEq <= R) {
            int jj = (int) jEq;
            if (A[d] == A[jj]) cnt--;
        }
        return cnt;
